<template>
  <v-container fluid class="tpl-root pa-0">
    <!-- ═══════════════════════════════════════════ HERO ══ -->
    <div class="tpl-hero">
      <div class="tpl-hero__left">
        <div class="tpl-hero__icon">
          <v-icon color="white" size="22">mdi-clipboard-list-outline</v-icon>
        </div>
        <div>
          <div class="tpl-hero__title">My Trainings</div>
          <div class="tpl-hero__sub">
            Training you've requested, plus HR-recommended training you've
            been approved for — latest first
          </div>
        </div>
      </div>
      <div class="tpl-hero__stat" v-if="!loading">
        <div class="tpl-hero__stat-val">{{ totalItems }}</div>
        <div class="tpl-hero__stat-lbl">Total Trainings</div>
      </div>
    </div>

    <!-- ═══════════════════════════════ LATEST APPROVED ══ -->
    <v-container
      fluid
      class="pa-4 pb-0"
      v-if="!loading && latestApproved.length"
    >
      <div class="tpl-approved-head">
        <v-icon color="green darken-2" size="18" class="mr-1"
          >mdi-check-decagram</v-icon
        >
        <span class="tpl-approved-head__title">Latest Approved Training</span>
      </div>
      <v-row dense>
        <v-col
          v-for="item in latestApproved"
          :key="item.source + '-' + item.id"
          cols="12"
          sm="6"
        >
          <v-card outlined class="tpl-approved-card" @click="viewRequest(item)">
            <div class="tpl-approved-card__top">
              <v-chip
                x-small
                outlined
                :color="
                  item.source === 'recommended'
                    ? 'purple darken-1'
                    : 'blue-grey darken-1'
                "
              >
                <v-icon x-small left>
                  {{
                    item.source === "recommended"
                      ? "mdi-account-star-outline"
                      : "mdi-account-edit-outline"
                  }}
                </v-icon>
                {{ item.source === "recommended" ? "HR Recommended" : "Self-Requested" }}
              </v-chip>
              <v-chip x-small color="green darken-1" dark>
                <v-icon x-small left>mdi-check-circle-outline</v-icon>
                Approved
              </v-chip>
            </div>
            <div class="tpl-approved-card__course">{{ item.course || "—" }}</div>
            <div class="tpl-approved-card__meta">
              <span v-if="item.typeDisplay">{{ item.typeDisplay }}</span>
