                @change="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="2">
              <v-select
                v-model="filters.source"
                :items="sourceOptions"
                label="Source"
                prepend-inner-icon="mdi-source-branch"
                outlined
                dense
                hide-details
                clearable
                @change="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="2">
              <v-text-field
                v-model="filters.startDateFrom"
                label="Start Date From"
                type="date"
                outlined
                dense
                hide-details
                clearable
                @input="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="2">
              <v-text-field
                v-model="filters.startDateTo"
                label="Start Date To"
                type="date"
                outlined
                dense
                hide-details
                clearable
                @input="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="2">
              <v-text-field
                v-model="filters.endDateFrom"
                label="End Date From"
                type="date"
                outlined
                dense
                hide-details
                clearable
                @input="onFilterChange"
              />
            </v-col>
            <v-col cols="12" sm="1" class="d-flex justify-end">
              <v-btn
                text
                small
                color="grey darken-1"
                :disabled="!hasActiveFilters"
                @click="clearFilters"
              >
                <v-icon left small>mdi-filter-remove</v-icon>
                Clear
              </v-btn>
            </v-col>
          </v-row>
        </v-card-text>
      </v-card>

      <!-- Table -->
      <v-card outlined>
        <v-card-title class="indigo darken-2 white--text py-3">
          <v-icon left color="white">mdi-clipboard-list-outline</v-icon>
          <div>
            <div class="subtitle-1 font-weight-bold">
              Training Plans &amp; Recommendations
            </div>
            <div class="caption font-weight-regular" style="opacity:.7">
              Click a row to view full details
            </div>
          </div>
          <v-spacer />
          <v-chip
            v-if="hasActiveFilters"
            small
            color="amber lighten-4"
            text-color="amber darken-4"
            class="mr-2"
          >
            <v-icon x-small left>mdi-filter</v-icon>
            Filtered
          </v-chip>
          <v-chip small color="white" text-color="indigo darken-2">
            {{ totalItems }} total
          </v-chip>
        </v-card-title>

        <v-data-table
          :headers="headers"
          :items="filteredItems"
          :loading="loading"
          :items-per-page="10"
          :footer-props="{ itemsPerPageOptions: [10, 20, 50] }"
          class="tpl-table"
          loading-text="Loading trainings…"
          no-data-text="No training plans or recommendations found"
          no-results-text="No trainings match the current filters"
          @click:row="viewRequest"
        >
          <!-- Course -->
          <template v-slot:item.course="{ item }">
            <div class="font-weight-medium">{{ item.course || "—" }}</div>
            <div class="caption grey--text">{{ item.typeDisplay }}</div>
          </template>

          <!-- Source -->
          <template v-slot:item.source="{ item }">
            <v-chip
              x-small
              outlined
              :color="item.source === 'recommended' ? 'purple darken-1' : 'blue-grey darken-1'"
            >
              <v-icon x-small left>
                {{ item.source === "recommended" ? "mdi-account-star-outline" : "mdi-account-edit-outline" }}
              </v-icon>
              {{ item.source === "recommended" ? "HR Recommended" : "Self-Requested" }}
            </v-chip>
          </template>

          <!-- Start date -->
          <template v-slot:item.startDate="{ item }">
            <span class="caption">{{ formatDate(item.startDate) }}</span>
          </template>

          <!-- End date -->
          <template v-slot:item.endDate="{ item }">
            <span class="caption">{{ formatDate(item.endDate) }}</span>
          </template>

          <!-- Duration — calculated -->
          <template v-slot:item.duration="{ item }">
            <v-chip
              x-small
              outlined
              color="blue darken-1"
              v-if="item.startDate && item.endDate"
            >
              <v-icon x-small left>mdi-clock-outline</v-icon>
              {{ calcDuration(item.startDate, item.endDate) }}
            </v-chip>
            <span v-else class="caption grey--text">—</span>
          </template>

          <!-- Status -->
          <template v-slot:item.status="{ item }">
            <v-chip x-small :color="statusColor(item.status)" dark>
              <v-icon x-small left>{{ statusIcon(item.status) }}</v-icon>
              {{ item.statusDisplay || item.status }}
            </v-chip>
          </template>

          <!-- Submitted date -->
          <template v-slot:item.submittedDate="{ item }">
            <span class="caption grey--text">{{ item.submittedDate }}</span>
          </template>

          <!-- Actions -->
          <template v-slot:item.actions="{ item }">
            <v-btn icon x-small color="primary" @click.stop="viewRequest(item)">
              <v-icon small>mdi-eye</v-icon>
            </v-btn>
          </template>

          <!-- Loading overlay -->
          <template v-slot:progress>
            <v-progress-linear indeterminate color="indigo" />
          </template>
        </v-data-table>
      </v-card>
    </v-container>
  </v-container>
</template>

<script>
import generalMixin from "../../mixins/general";

const EXT = {
  NEED: "http://ihris.org/fhir/StructureDefinition/training-need-reference",
  TYPE: "http://ihris.org/fhir/StructureDefinition/training-type",
  START: "http://ihris.org/fhir/StructureDefinition/start-date",
  END: "http://ihris.org/fhir/StructureDefinition/end-date",
  QUAL_NAME: "http://ihris.org/fhir/StructureDefinition/qualification-name",
  QUAL_OTHER: "http://ihris.org/fhir/StructureDefinition/qualification-name-other",
  QUAL_LEVEL: "http://ihris.org/fhir/StructureDefinition/qualification-level",
  COURSE_OLD: "http://ihris.org/fhir/StructureDefinition/planning-course",
  INSTITUTION: "http://ihris.org/fhir/StructureDefinition/planning-institution",
  METHODOLOGY: "http://ihris.org/fhir/StructureDefinition/learning-methodology",
  COMMENTS: "http://ihris.org/fhir/StructureDefinition/comments",
  STATUS: "http://ihris.org/fhir/StructureDefinition/request-status",
  EVENT_DATE: "http://ihris.org/fhir/StructureDefinition/event-date",
  NEED_NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
  PRACTITIONER:
    "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
};

const PROFILE =
  "http://ihris.org/fhir/StructureDefinition/training-plan-request-profile";

// HR-recommended trainings live across three linked resources:
//   TrainingRecommendation (the course/dates HR proposed)
//     ← training-recommendation-reference ←
//   TrainingRecommendationResponse (HOD's nominated staff list)
//     ← training-recommendation-response-reference ←
//   HRTrainingRecommendationReview (HR's final approved/rejected decision)
// Only responses with an *approved* review are shown to staff.
const REC_RESPONSE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/training-recommendation-response-profile";
const REC_REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/hr-training-recommendation-review-profile";
const REC_RESPONSE_EXT = {
  RECOMMENDATION_REF:
    "http://ihris.org/fhir/StructureDefinition/training-recommendation-reference",
};
const REC_REVIEW_EXT = {
  STATUS: "http://ihris.org/fhir/StructureDefinition/review-status",
  RESPONSE_REF:
    "http://ihris.org/fhir/StructureDefinition/training-recommendation-response-reference",
};

export default {
  name: "TrainingPlanList",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      loading: true,
      // Both sources are fetched in full and merged — per-staff training
      // counts are small enough that local pagination/filtering over the
      // combined list is simpler than trying to keep two different FHIR
      // resource types server-paginated in lockstep.
      allItems: [],
      totalItems: 0,

      filters: {
        course: "",
        status: null,
        source: null,
        startDateFrom: null,
        startDateTo: null,
        endDateFrom: null,
      },

      statusOptions: [
        { text: "Approved", value: "approved" },
        { text: "Under Supervisor Review", value: "undersupervisorreview" },
        { text: "Under HOD Review", value: "underhodreview" },
        { text: "Under HR Review", value: "underhrreview" },
        { text: "Under PS Review", value: "underpsreview" },
        { text: "Rejected", value: "rejected" },
      ],

      sourceOptions: [
        { text: "Self-Requested", value: "selfrequested" },
        { text: "HR Recommended", value: "recommended" },
      ],

      headers: [
        { text: "Course / Program", value: "course", sortable: false },
        { text: "Source", value: "source", sortable: false },
        { text: "Start Date", value: "startDate", sortable: false },
        { text: "End Date", value: "endDate", sortable: false },
        { text: "Duration", value: "duration", sortable: false },
        { text: "Status", value: "status", sortable: false },
        { text: "Submitted", value: "submittedDate", sortable: false },
        {
          text: "",
          value: "actions",
          sortable: false,
          align: "end",
          width: "48px",
        },
      ],
    };
  },

  computed: {
    practitionerId() {
      return this.queries?.practitioner || this.loggedInStaff.practitioner;
    },

    // allItems is already sorted latest-first (see fetchAll), so the first
    // two approved entries are simply the two most recent approvals,
    // regardless of source.
    latestApproved() {
      return this.allItems.filter((i) => i.status === "approved").slice(0, 2);
    },

    hasActiveFilters() {
      return !!(
        this.filters.course ||
        this.filters.status ||
        this.filters.source ||
        this.filters.startDateFrom ||
        this.filters.startDateTo ||
        this.filters.endDateFrom
      );
    },

    // Client-side filter applied on top of the merged self-requested +
    // recommended list
    filteredItems() {
      let items = this.allItems;

      if (this.filters.course) {
        const q = this.filters.course.toLowerCase();
        items = items.filter((i) => (i.course || "").toLowerCase().includes(q));
      }

      if (this.filters.status) {
        items = items.filter((i) => i.status === this.filters.status);
      }

      if (this.filters.source) {
        items = items.filter((i) => i.source === this.filters.source);
      }

      if (this.filters.startDateFrom) {
        items = items.filter((i) => i.startDate >= this.filters.startDateFrom);
      }

      if (this.filters.startDateTo) {
        items = items.filter((i) => i.startDate <= this.filters.startDateTo);
      }

      if (this.filters.endDateFrom) {
        items = items.filter((i) => i.endDate >= this.filters.endDateFrom);
      }

      return items;
    },
  },

  watch: {
    loadingUserData: {
      immediate: true,
      async handler(isLoading) {
        if (isLoading === false) {
          await this.fetchAll();
        }
      },
    },
  },

  methods: {
    // ── FETCH ──────────────────────────────────────────────────────────
    async fetchAll() {
      if (!this.practitionerId) return;

      this.loading = true;
      try {
        const [selfItems, recommendedItems] = await Promise.all([
          this.fetchSelfRequested(),
          this.fetchRecommended(),
        ]);

        this.allItems = [...selfItems, ...recommendedItems].sort((a, b) =>
          (b.sortDate || "").localeCompare(a.sortDate || ""),
        );
        this.totalItems = this.allItems.length;
      } catch (err) {
        console.error("Error fetching trainings:", err);
        this.allItems = [];
        this.totalItems = 0;
      } finally {
        this.loading = false;
      }
    },

    async fetchSelfRequested() {
      try {
        const params = new URLSearchParams({
          _profile: PROFILE,
          practitioner: `Practitioner/${this.practitionerId}`,
          _sort: "-_lastUpdated",
          _count: 200,
        });
        const resp = await fetch(`/fhir/Basic?${params}`);
        const bundle = await resp.json();
        return (bundle.entry || []).map((e) =>
          this.processResource(e.resource),
        );
      } catch (err) {
        console.error("Error fetching self-requested training plans:", err);
        return [];
      }
    },

    // HR-recommended trainings, filtered down to only those where HR has
    // approved this staff member's nomination (see comment near the
    // REC_RESPONSE_PROFILE/REC_REVIEW_PROFILE constants above).
    async fetchRecommended() {
      try {
        const respParams = new URLSearchParams({
          _profile: REC_RESPONSE_PROFILE,
          practitioner: `Practitioner/${this.practitionerId}`,
          _count: 200,
        });
        const respBundle = await (
          await fetch(`/fhir/Basic?${respParams}`)
        ).json();
        const responses = (respBundle.entry || []).map((e) => e.resource);
        if (!responses.length) return [];

        const reviewParams = new URLSearchParams({
          _profile: REC_REVIEW_PROFILE,
          trainingrecommendationresponse: responses
            .map((r) => `Basic/${r.id}`)
            .join(","),
          _count: 200,
        });
        const reviewBundle = await (
          await fetch(`/fhir/Basic?${reviewParams}`)
        ).json();

        const approvedResponseIds = new Set();
        for (const e of reviewBundle.entry || []) {
          const review = e.resource;
          const reviewExt = review.extension || [];
          const statusCode = reviewExt.find(
            (x) => x.url === REC_REVIEW_EXT.STATUS,
          )?.valueCoding?.code;
          if (statusCode !== "approved") continue;
          const respRef = reviewExt.find(
            (x) => x.url === REC_REVIEW_EXT.RESPONSE_REF,
          )?.valueReference?.reference;
          if (respRef) approvedResponseIds.add(respRef.split("/")[1]);
        }

        const approvedResponses = responses.filter((r) =>
          approvedResponseIds.has(r.id),
        );
        if (!approvedResponses.length) return []

        const recIds = [
          ...new Set(
            approvedResponses
              .map(
                (r) =>
                  r.extension?.find(
                    (x) => x.url === REC_RESPONSE_EXT.RECOMMENDATION_REF,
                  )?.valueReference?.reference,
              )
              .filter(Boolean)
              .map((ref) => ref.split("/")[1]),
          ),
        ];
        const recommendationById = {};
        await Promise.all(
          recIds.map(async (id) => {
            try {
              const res = await fetch(`/fhir/Basic/${id}`);
              if (res.ok) recommendationById[id] = await res.json();
            } catch (_) {
              /* leave absent */
            }
          }),
        );

        return approvedResponses.map((response) => {
          const recRef = response.extension?.find(
            (x) => x.url === REC_RESPONSE_EXT.RECOMMENDATION_REF,
          )?.valueReference?.reference;
          const recId = recRef ? recRef.split("/")[1] : null;
          const recommendation = recId ? recommendationById[recId] : null;
          return this.processRecommendation(response, recommendation);
        });
      } catch (err) {
        console.error("Error fetching recommended trainings:", err);
        return [];
      }
    },

    // ── PROCESS FHIR RESOURCE (self-requested training plan) ───────────
    processResource(resource) {
      const ext = resource.extension || [];
      const find = (url) => ext.find((e) => e.url === url);

      const typeExt = find(EXT.TYPE);
      const statusExt = find(EXT.STATUS);
      const startExt = find(EXT.START);
      const endExt = find(EXT.END);
      const eventDate = find(EXT.EVENT_DATE);

      const submittedDate =
        eventDate?.valueDate ||
        (resource.meta?.lastUpdated
          ? resource.meta.lastUpdated.split("T")[0]
          : null);

      return {
        id: resource.id,
        source: "selfrequested",
        course:
          find(EXT.QUAL_OTHER)?.valueString ||
          find(EXT.QUAL_NAME)?.valueReference?.display ||
          find(EXT.COURSE_OLD)?.valueString ||
          "",
        institution: find(EXT.INSTITUTION)?.valueString || "",
        comments: find(EXT.COMMENTS)?.valueString || "",
        methodology: find(EXT.METHODOLOGY)?.valueCoding?.display || "",
        type: typeExt?.valueCoding?.code || "",
        typeDisplay: typeExt?.valueCoding?.display || "",
        startDate: startExt?.valueDate || "",
        endDate: endExt?.valueDate || "",
        status: statusExt?.valueCoding?.code || "pending",
        statusDisplay: statusExt?.valueCoding?.display || "Pending",
        submittedDate: this.formatDate(submittedDate),
        sortDate: submittedDate || "",
        needRef: find(EXT.NEED)?.valueReference?.reference || "",
      };
    },

    // ── PROCESS FHIR RESOURCE (approved recommended training) ──────────
    processRecommendation(response, recommendation) {
      const recExt = recommendation?.extension || [];
      const findRec = (url) => recExt.find((e) => e.url === url);

      const typeExt = findRec(EXT.TYPE);
      const startExt = findRec(EXT.START);
      const endExt = findRec(EXT.END);
      const eventDateExt = (response.extension || []).find(
        (e) => e.url === EXT.EVENT_DATE,
      );

      return {
        id: response.id,
        recommendationId: recommendation?.id || null,
        source: "recommended",
        course:
          findRec(EXT.QUAL_OTHER)?.valueString ||
          findRec(EXT.QUAL_NAME)?.valueReference?.display ||
          findRec(EXT.NEED_NAME)?.valueString ||
          "",
        type: typeExt?.valueCoding?.code || "",
        typeDisplay: typeExt?.valueCoding?.display || "",
        startDate: startExt?.valueDate || "",
        endDate: endExt?.valueDate || "",
        status: "approved",
        statusDisplay: "Approved",
        submittedDate: this.formatDate(eventDateExt?.valueDate),
        sortDate: eventDateExt?.valueDate || "",
      };
    },

    // ── FILTERS ────────────────────────────────────────────────────────
    onFilterChange() {
      // Filtering is purely client-side over the already-fetched merged
      // list now, so there's no server page to reset — v-data-table
      // resets its own internal page when the filtered item count changes.
    },

    clearFilters() {
      this.filters = {
        course: "",
        status: null,
        source: null,
        startDateFrom: null,
        startDateTo: null,
        endDateFrom: null,
      };
    },

    // ── NAVIGATION ─────────────────────────────────────────────────────
    viewRequest(item) {
      const path = this.queries?.path || "";
      if (item.source === "recommended") {
        const params = new URLSearchParams({
          path,
          practitioner: this.practitionerId,
          responseid: item.id,
        });
        window.location.href = `/custom/training-recommendation-view?${params}`;
        return;
      }
      const params = new URLSearchParams({
        path,
        practitioner: this.practitionerId,
        request: item.id,
      });
      window.location.href = `/custom/training-plan-request-view?${params}`;
    },

    // ── HELPERS ────────────────────────────────────────────────────────
    /**
     * Calculate duration from start/end dates.
     * Returns e.g. "3m 5d", "1y 2m", "45d"
     * Does NOT use the deprecated duration field on the resource.
     */
    calcDuration(startDate, endDate) {
      if (!startDate || !endDate) return "—";
      try {
        const start = new Date(startDate);
        const end = new Date(endDate);
        if (isNaN(start) || isNaN(end) || end < start) return "—";

        let years = end.getFullYear() - start.getFullYear();
        let months = end.getMonth() - start.getMonth();
        let days = end.getDate() - start.getDate();

        if (days < 0) {
          months -= 1;
          // days in previous month
          const prev = new Date(end.getFullYear(), end.getMonth(), 0);
          days += prev.getDate();
        }
        if (months < 0) {
          years -= 1;
          months += 12;
        }

        const parts = [];
        if (years > 0) parts.push(`${years}y`);
        if (months > 0) parts.push(`${months}m`);
        if (days > 0 && years === 0) parts.push(`${days}d`);
        return parts.length ? parts.join(" ") : "< 1d";
      } catch {
        return "—";
      }
    },

    formatDate(dateString) {
      if (!dateString) return "—";
      try {
        return new Date(dateString).toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        });
      } catch {
        return dateString;
      }
    },

    statusColor(code) {
      const map = {
        pending: "grey darken-1",
        underreview: "orange darken-1",
        approved: "green darken-1",
        rejected: "red darken-1",
        withdrawn: "brown darken-1",
      };
      return map[code] || "grey";
    },

    statusIcon(code) {
      const map = {
        pending: "mdi-clock-outline",
        underreview: "mdi-progress-check",
        approved: "mdi-check-circle-outline",
        rejected: "mdi-close-circle-outline",
        withdrawn: "mdi-cancel",
      };
      return map[code] || "mdi-help-circle-outline";
    },
  },
  async created() {
    this.loading = true;

    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    if (!this.loggedInStaff.practitioner) {
      this.$store.commit("setMessage", {
        type: "error",
        text: "You are not a staff",
      });
      setTimeout(() => {
        this.$router.go(-1);
      }, 2000);
    }
  },
};
</script>

